head.script:
scwin.gridView1_onscrollend = function() {
    eventIsActived = true;
    ngmf.layerAlert("gridView1_onscrollend");
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id+"gridView1_cell_13_1").innerText == '1' && eventIsActived == false;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('#gridView1_cell_13_1').is(':focus');
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭에서 w2:gridView 의 filterFocusMode 를 확인한다.
    //1. In the Source tab, check the filterFocusMode of w2: gridView.
    //Verify step 1. filterFocusMode="followfocus"
    //1. filterFocusMode = "followfocus"
    //Test step 2. 브라우저에서 col2 열의 첫번째 행 (1)에 포커스를 주고, 헤더를 더블클릭을 2번 한다.
    //2. In the browser, give focus to the first row (1) of the col2 column, and double-click the header twice.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column9')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column9')");
    //Verify step 2. 해당 열이 내림차순으로 정렬되면서 1이 맨아래로 이동된다. (전버전에서는 내림차순으로 정렬시 onscrollend 이벤트가 동작하였음.) 
    //2. The column is moved in the descending order and 1 is moved to the bottom. (In previous versions, the onscrollend event worked when sorting in descending order.)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.eventIsActived = false;
    window.data = [];
    for (var i = 0; i < 20; i++) {
        for (var j = 0; j < 6; j++) {
            data.push(6 * i + j);
        }
    }
    dataList1.setData(data);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
